    assert Arrays.equals(solution.longestNiceSubstring("Bb"), Bb);
    assert Arrays.equals(solution.longestNiceSubstring("aAbBcCdDeEfFgG"), aAbBcCdDeEfFgG);
    assert Arrays.equals(solution.longestNiceSubstring("c"), null);
    assert Arrays.equals(solution.longestNiceSubstring("aBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz"), BbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz);
